    let num: f64 = u
        .iter()
        .zip(u_ref.iter())
        .map(|(&a, &b)| (a - b).powi(2))
        .sum::<f64>()
        .sqrt();
    let den: f64 = u_ref.iter().map(|x| x * x).sum::<f64>().sqrt();
    if den < 1e-300 { 0.0 } else { num / den }
}

