fn log_log_fit(x: &[f64], y: &[f64]) -> (f64, f64) {
    let mut lx = Vec::new();
    let mut ly = Vec::new();

    for (&xi, &yi) in x.iter().zip(y.iter()) {
        if xi > 0.0 && yi > 0.0 {
            lx.push(xi.ln());
            ly.push(yi.ln());
        }
    }

    let n = lx.len() as f64;
    if n < 2.0 {
        return (0.0, 0.0);
    }

    let mean_lx = lx.iter().sum::<f64>() / n;
    let mean_ly = ly.iter().sum::<f64>() / n;

    let mut num = 0.0_f64;
    let mut den = 0.0_f64;
    for (xi, yi) in lx.iter().zip(ly.iter()) {
        let dx = xi - mean_lx;
        let dy = yi - mean_ly;
        num += dx * dy;
        den += dx * dx;
    }

    if den.abs() < 1e-30 {
        return (0.0, mean_ly);
    }

    let slope = num / den;
    let intercept = mean_ly - slope * mean_lx;
    (slope, intercept)
