fn periodic_neighbor(
    x: i32,
    y: i32,
    z: i32,
    cx: i32,
    cy: i32,
    cz: i32,
    nx: i32,
    ny: i32,
    nz: i32,
    nx_u: usize,
) -> usize {
    let mut nx_i = x + cx;
    let mut ny_i = y + cy;
    let mut nz_i = z + cz;
    nx_i -= nx * (nx_i / nx);
    if nx_i < 0 {
        nx_i += nx;
    }
    ny_i -= ny * (ny_i / ny);
    if ny_i < 0 {
        ny_i += ny;
    }
    nz_i -= nz * (nz_i / nz);
    if nz_i < 0 {
        nz_i += nz;
    }
    let nx_area = nx_u * (ny as usize);
    (nz_i as usize) * nx_area + (ny_i as usize) * nx_u + (nx_i as usize)
}

